namespace BoatsNBeasts.Core;

public static partial class FarLedger
{
    static CampaignArc Waxwing() => CampaignArc.Create("Waxwing Roads", "The Courier Who Came Second",
        "A flock with red sealing-wax wings brings the crew seven reports of the same island walking. Six couriers flew straight. Kest, who flew around the back, is the only one who saw what frightened it.",
        "Kest’s split-second finish ribbon, mended down the middle",
        new("Kest  /  wind courier",
            "Who carries the warning over the lee ridge?",
            "Kest can take a sealed warning through the high thermals alone. The coast mothers can relay an open copy below the cloud, changing its bearings as the islands move. There is wax for one issue.",
            "Back Kest’s high flight",
            "Give the coast the message",
            "Kest tucks the only copy against their ribs. For once the fastest courier has to wait for a witness.",
            "The seal is broken in front of the mothers. They make seven thimbles of wax and send seven messengers out."),
        11,
        [
            Crossing("wake-wax-late", SeaDuty.Hunt, "A Second Place to Stand",
                "Kest lands on the yardarm with one leg stiff and a bundle of flags in their teeth. Their companion courier is a day late. The route below is strewn with little red feathers.",
                "Trace the strip of fallen wax to the missing courier.", "Sealbreaker Kite",
                "The missing courier is flying upside down below a walking island. She has stayed to watch a family stranded under the moving lee.", 8, SeaJob.Track, SeaJob.Sound, SeaJob.DriveOff),
            Landfall("wake-wax-lee", "Under the Seal",
                "Every courier carries wings made from household candle ends. A whole flight has melted onto the underside of the island. Kest knows which pair belongs to the woman below.", "Wickjaw Heron",
                "The woman walks out with two children strapped into her empty wing frame. Kest calls their names before asking about the race.", 8,
                At(LandingAction.Brace, YardSite.West, "Wing frame", "Brace the lightest frame under the shelf"),
                At(LandingAction.Cut, YardSite.East, "Wax fingers", "Cut the fused finger loops clear"),
                At(LandingAction.Guide, YardSite.Stairs, "Lee courier", "Bring the stranded courier and children to the steps")),
            Crossing("wake-wax-high", SeaDuty.Convoy, "The High Envelope",
                "Kest could make the crossing alone, but an unwitnessed warning has no standing at the lee station. Vara volunteers to tow the witness in an old kite basket.",
                "Keep the witness under Kest’s red wing across the thermals.", "Basketbill",
                "The basket arrives first. Kest asks Vara to write that fact down before anyone can improve the story.", 8, SeaJob.Guide, SeaJob.Relieve, SeaJob.Tow),
            Landfall("wake-wax-witness", "The Wrong Finish Line",
                "A copper camera photographs every winning courier at the ridge. Its plate also holds the only clear picture of the walking island and the family underneath.", "Shutter Drake",
                "Kest cuts their own face out of the first-place picture. The children and the underside of the island fill the enlargement.", 9,
                At(LandingAction.Turn, YardSite.West, "Dark slide", "Close the plate holder to daylight"),
                At(LandingAction.Haul, YardSite.Fallen, "Copper plate", "Hook the plate out of the finish camera"),
                At(LandingAction.Seat, YardSite.East, "Printing frame", "Seat the underside image in the big frame")),
            Crossing("wake-wax-oath", SeaDuty.Salvage, "A Tin of Used Wings",
                "Kest kept the wing tips from every flight they abandoned. A weather station used the old wax to seal the year’s bearings. The station has since gone under.",
                "Raise Kest’s wax tin and preserve the bearing marks.", "Weathercock Ray",
                "Three abandoned flights led to shelters invisible on the winning chart. The lee pilots mark all three in red.", 8, SeaJob.Sound, SeaJob.Salvage, SeaJob.Unload),
            Crossing("wake-wax-shadow", SeaDuty.Sounding, "The Shape Between Birds",
                "Kest asks the crew to plot the empty spaces in a flight of couriers. Seen together, the holes trace the nursery route of the moving islands.",
                "Chart the sheltered corridor between the flights.", "Red Quill",
                "Kest ties their old finish ribbon between the two lookout posts. It twitches before the course changes. The crew can now steer by it.", 8, SeaJob.Track, SeaJob.Relay, SeaJob.Sound)
        ],
        Crossing("wake-wax-mouth", SeaDuty.Blockade, "By Word of Wing",
            "The seven local couriers change the bearing aloud as the sea turns underneath them. A station judge keeps confiscating messages that disagree with the first one.",
            "Carry the living relay beyond the station judge.", "Seventh Seal",
            "All seven messages reach the same harbor by different routes. Kest collects the errors and charts which islands chose to turn.", 8, SeaJob.Cut, SeaJob.Relay, SeaJob.Guide));

    static IslandStory[] WaxwingIsles() =>
    [
        Isle("Waxwing Roads",11,"Matchbox Roost","Yali, wing mender",
            "The young couriers sleep in numbered matchboxes. The boxes have blown off their shelf with the apprentice roster still pasted underneath. Yali has a file for crooked wicks and no idea how many birds are missing.", "A copper matchbox pierced with air holes",
            new PostLetter("A photograph with eight pointed shadows",
                "I count eight shadows and seven birds. The eighth shadow has walked across the picture since yesterday. Do keep the lid loose.",
                "Nell puts the picture outside. By tea the eighth bird has flown."),
            Crossing("wake-match-drawer", SeaDuty.Salvage, "Drawers in the Sky",
                "Each missing drawer trails a short line of sparks. Yali can read the box numbers from the pattern they leave on the water.",
                "Collect the floating dormitory drawers in their roster order.", "Phosphor Skate",
                "Drawer eight holds a warm stone instead of a bird. Yali has been feeding the stone with the rest of the rookery for years.", 8, SeaJob.Track, SeaJob.Salvage, SeaJob.Unload),
            Landfall("wake-match-stone", "The Eighth Bed",
                "The stone has hatched into a walking spark. The fire marshal shut the rookery doors on hearing the news. Its seven siblings are trying to post themselves under the door.", "Latchwing Moth",
                "Yali carries the spark outside in the perforated matchbox. Seven birds land on the lid and doze.", 8,
                At(LandingAction.Haul, YardSite.West, "Drawer rack", "Pull the rack clear of the shutter"),
                At(LandingAction.Brace, YardSite.East, "Cool sleeve", "Hold the sleeve around the warm stone"),
                At(LandingAction.Guide, YardSite.Stairs, "Wing mender", "Escort Yali and the hatchling into the yard")),
            Crossing("wake-match-warm", SeaDuty.Hunt, "A Stone Learns to Fly",
                "The hatchling cannot fly but it can heat the air under seven small wings. The flock rises every time it hiccups.",
                "Follow the warm column into the first flight school.", "Hiccup Swift",
                "The flock comes down in a tidy stack. Yali notes that the hatchling is the only one with a perfect landing.", 8, SeaJob.Track, SeaJob.Bait, SeaJob.Relay),
            Landfall("wake-match-name", "A Bed Without a Number",
                "The roster only admits creatures with wings. Kest finds a drawer underneath the shelf with their own scratched-out childhood name on it.", "Roster Weevil",
                "The eighth bed fits underneath the first seven. Yali writes the spark’s name in the margin where Kest can see it.", 8,
                At(LandingAction.Cut, YardSite.East, "Old roster", "Lift the pasted roster without tearing the names"),
                At(LandingAction.Seat, YardSite.West, "Eighth drawer", "Set the spark’s drawer under the flying beds"),
                At(LandingAction.Turn, YardSite.Crane, "Flight board", "Register the whole flock together"))),
        Isle("Waxwing Roads",11,"Bellflower Exchange","Min, voice broker",
            "Min sells the sound of home to couriers who travel too far for letters. The bellflowers have begun repeating the last word of a stranger who never paid.", "A bellflower in a soundproof eggcup",
            new PostLetter("A clipping that whispers left when turned right",
                "I cut the flower after it stopped speaking. It says different things to different ears. Could someone who never knew me try it once?",
                "Vara hears a little child saying again. Min sends a second clipping."),
            Crossing("wake-bloom-last", SeaDuty.Sounding, "The Unbought Word",
                "Every bellflower leans toward the sound it remembers. At the root of the exchange, an unpaid voice says the same word against the wind.",
                "Triangulate the voice between the copper flower beds.", "Petal Piper",
                "The word is left. A missing ferry pilot has been correcting the harbor course from inside the echo.", 8, SeaJob.Sound, SeaJob.Relay, SeaJob.Track),
            Landfall("wake-bloom-stem", "A Voice in the Stem",
                "Min grafted the voice onto a flower that only opens when its owner breathes. The pilot’s sister offers to breathe along with it.", "Graft Knife Wasp",
                "Two breaths bring the flower fully open. Min hears a rowlock squeak behind the voice and recognizes the pilot’s old practice boat.", 8,
                At(LandingAction.Brace, YardSite.West, "Bell stem", "Brace the breathing stem against the wind"),
                At(LandingAction.Haul, YardSite.East, "Copper throat", "Lift the copper throat from the graft"),
                At(LandingAction.Turn, YardSite.Crane, "Listening cup", "Open the cup for the pilot’s sister")),
            Crossing("wake-bloom-ferry", SeaDuty.Convoy, "Practice Water",
                "The pilot is stranded in the little loop of water where she learned to row. Her practice course has wrapped around the island three times.",
                "Guide her sister’s boat down the repeated channel.", "Repeat Gull",
                "The pilot takes the left oar and her sister takes the right. For the first time in days the boat goes straight.", 8, SeaJob.Guide, SeaJob.Relieve, SeaJob.Tow),
            Landfall("wake-bloom-free", "Nobody Owns Left",
                "Min kept a brass tariff on every spoken direction. Kest offers to trade their race winnings for the release of one common word.", "Toll Funnel Beetle",
                "The bellflowers call left to anyone who passes. Min charges for right for precisely eleven minutes before taking that sign down too.", 8,
                At(LandingAction.Haul, YardSite.Fallen, "Tariff plate", "Lift the plate from the speaking root"),
                At(LandingAction.Cut, YardSite.East, "Coin string", "Cut the coin string from the bell"),
                At(LandingAction.Seat, YardSite.West, "Free cup", "Fit the free listening cup below the flower"))),
        Isle("Waxwing Roads",11,"Pin-Feather Marish","Tem, roof fletcher",
            "Tem thatches roofs with the feathers the couriers shed. A new roof has learned the courier route and keeps taking off with the laundry attached.", "A blue feather held in a roofing nail",
            new PostLetter("A very small clothes peg",
                "We have started a laundry post. So far only one sock has been delivered correctly. The other has sent a postcard from across the ridge.",
                "Lio makes the little peg into a bookmark for the sock’s postcard."),
            Crossing("wake-pin-roof", SeaDuty.Hunt, "Follow That Roof",
                "Tem knows his missing roofs by their washing lines. A white shirt with three sleeves belongs to the only family who will notice a missing roof before lunch.",
                "Track the airborne wash house over the ferry lanes.", "Roof Tern",
                "The roof has nested over a courier too old to fly. The missing third sleeve is full of chicks.", 8, SeaJob.Track, SeaJob.Bait, SeaJob.DriveOff),
            Landfall("wake-pin-eaves", "Low Eaves",
                "The retired courier wants to keep the chicks warm without depriving the family of a roof. Tem can split the thatch along the line of flight.", "Chimney Vixen",
                "The lower half drifts home by itself. The retired courier puts the higher half on like a cape.", 8,
                At(LandingAction.Brace, YardSite.West, "Nest sling", "Secure the sling under the warmest eave"),
                At(LandingAction.Cut, YardSite.Fallen, "Thatch seam", "Cut along the line of blue pinfeathers"),
                At(LandingAction.Guide, YardSite.Stairs, "Retired courier", "Escort the retired courier to her own roof")),
            Crossing("wake-pin-line", SeaDuty.Convoy, "Laundry Express",
                "The family hang their blue shirt on a line between the two roofs. The chicks use the sleeves as wind socks until the first squall blows through.",
                "Keep both roofs level until the chicks can roost.", "Sleeve Squall",
                "The three-sleeved shirt points to three different harbors. Tem hangs his socks from the quietest sleeve.", 8, SeaJob.Tow, SeaJob.Relieve, SeaJob.Relay),
            Landfall("wake-pin-perch", "The Spare Rafter",
                "Tem returns with a single rafter for the old courier’s porch. The chicks have grown too large for their sleeve and too proud for the spare bedroom.", "Rafter Mole",
                "At sunset seven little roofs settle on the spare rafter. Tem sleeps under the biggest one, quite dry.", 8,
                At(LandingAction.Seat, YardSite.East, "Porch rafter", "Seat the new perch above the wash line"),
                At(LandingAction.Turn, YardSite.Crane, "Shutter stays", "Turn the shutter stays toward the evening lee"),
                At(LandingAction.Brace, YardSite.West, "Landing line", "Hold the line for the chicks’ first landing"))),
        Isle("Waxwing Roads",11,"Ravel Post","Ivi, envelope cutter",
            "Ivi cuts each envelope to fit its message. A letter about a very long absence has run out of the post office, down the slip and around three mooring buoys.", "A thimbleful of blue envelope paste",
            new PostLetter("An envelope around a spool of blank thread",
                "My brother answered in thread. He has always had trouble finding an ending. Please return as much as anybody can bear to read.",
                "Oren winds the thread around an empty button card and leaves the last inch loose."),
            Landfall("wake-ravel-length", "Letter on the Slip",
                "The letter crosses a busy capstan. Its author wants it back long enough to change the last line. Ivi has already cut herself reading it.", "Paperedge Cat",
                "The author crosses out a formal goodbye and writes breakfast on Tuesday. The letter immediately loses six feet.", 8,
                At(LandingAction.Brace, YardSite.West, "Capstan jaws", "Brace the jaws around the wet letter"),
                At(LandingAction.Cut, YardSite.East, "Tar twine", "Cut the tar twine away from the paper"),
                At(LandingAction.Haul, YardSite.Fallen, "Last page", "Hook the last page back into the office")),
            Crossing("wake-ravel-ink", SeaDuty.Salvage, "The Bit That Sank",
                "A single line of heavy iron ink has sunk to the bottom of the mail lane. The author remembers what it said and is afraid of seeing it again.",
                "Raise the heavy ink intact for its author.", "Ink Sink Ray",
                "The line reads I thought you would come. The author asks Ivi to leave it where it was in the letter.", 8, SeaJob.Track, SeaJob.Salvage, SeaJob.Unload),
            Crossing("wake-ravel-route", SeaDuty.Blockade, "Two Addresses Ago",
                "The addressee moved twice while the envelope was being made. The old station insists that a letter this long cannot be redirected without a second pilot.",
                "Carry the long letter beyond both forwarding booms.", "Forwarding Gull",
                "Kest stands at the stern with the last inch of letter folded into their pocket. It is just enough for the crossing.", 9, SeaJob.Cut, SeaJob.Tow, SeaJob.Relay),
            Landfall("wake-ravel-flap", "Dinner on Tuesday",
                "The letter has reached a door with a very thin slot. Ivi has brought her scissors. The author asks to hand over the first page himself.", "Slot Adder",
                "Two brothers read the rest at the kitchen table, passing each page back to Ivi to fold into smaller envelopes.", 8,
                At(LandingAction.Seat, YardSite.West, "Table leaf", "Fit the long leaf into the kitchen table"),
                At(LandingAction.Turn, YardSite.East, "Door slot", "Turn back the narrow slot cover"),
                At(LandingAction.Guide, YardSite.Stairs, "Letter writer", "Walk the writer to his brother’s door")))
    ];
}
